update_rule.pseudocode:
for each retailer r:
  if random() < supply_disruption_probability: incoming = 0 else incoming = Binomial(retailer_initial_inventory, retailer_restock_rate_per_day)
  add incoming after supply_delay_days via pipeline queue
  if stockout: adjust price upward; else converge toward mask_price_base
for each person p needing masks (mask_stock < masks_needed_next_k_days):
  demand = max(0, masks_per_day_per_person * 7 - p.mask_stock)
  effective_price = nearest_retailer.price
  purchase_qty = floor(demand * max(0, 1 + price_elasticity_of_demand * (effective_price - mask_price_base)))
  purchase_qty = min(purchase_qty, nearest_retailer.inventory)
  if purchase_qty > 0 and p.budget_daily * 7 >= effective_price * purchase_qty:
    decrement retailer.inventory; increment p.mask_stock; record transaction
record stockouts as fraction of retailers with inventory == 0

policy_active = (policy_required_workplace or policy_required_school or policy_required_retail or policy_required_transit or policy_required_outdoor)
for each location L:
  if L.type in {workplace, school, retail, transit, outdoor}:
    L.mask_policy_required = policy_required_<type>
for each person p present at L where L.mask_policy_required == true and p.mask_use_state == false:
  if Bernoulli(enforcement_probability * enforcement_strength):
    issue fine of fine_amount; record enforcement action; set signals.policy_compliance[p] = 1 for today
  else if Bernoulli(inspection_rate_per_location):
    issue warning; record enforcement action
